import AdPlacements from './components/AdPlacements.vue';
import { forumEnabled } from '../shared/features';
import { api, getToken, setToken } from './api';
import { type Row, eventCategories, postCategories, statusNames, roleNames, formatTime, eventState, canCancelSignup, signupLabel, newProfile, privacy, agreement } from '../shared/domain';

const checkinTarget = ref<Row | null>(null);
function beginCheckin(row: Row) { checkinTarget.value = row;close();go('checkin'); }
const proposalRevision = ref(0);
const chatTarget = ref<Row | null>(null);
const contactTarget = ref<Row | null>(null);
function chatMember(member: Row) { chatTarget.value = member;go('chat'); }
function contactMember(member: Row) { contactTarget.value = member;go('contacts'); }
const page = ref('home'), user = ref<Row | null>(null), stats = ref<Row>({}), events = ref<Row[]>([]), posts = ref<Row[]>([]), notices = ref<Row[]>([]), members = ref<Row[]>([]), signups = ref<Row[]>([]), ownPosts = ref<Row[]>([]);
const adminMembers = ref<Row[]>([]), adminPosts = ref<Row[]>([]), logs = ref<Row[]>([]), participants = ref<Row[]>([]);
const loading = ref(false), busy = ref(false), error = ref(''), message = ref(''), filter = ref('全部'), search = ref(''), adminTab = ref('members');
const modal = ref(''), form = ref<Row>({}), selected = ref<Row>({}), dialog = ref<HTMLDialogElement | null>(null), beforeModal = ref<HTMLElement | null>(null);
const staff = computed(() => !!user.value && ['superadmin', 'admin', 'organizer'].includes(user.value.role));
const { unread } = useChatUnread(() => user.value, api);
const approved = computed(() => user.value?.status === 'approved');
const nav = computed(() => [
  { id: 'home', label: '乡情首页', icon: 'home', group: '在这里，相聚' },
  { id: 'railway', label: '一凡说高铁', icon: 'train', group: '在这里，相聚' },
  { id: 'events', label: '乡情活动', icon: 'calendar', group: '在这里，相聚' },
  { id: 'gallery', label: '相聚相册', icon: 'book', group: '在这里，相聚' },
  { id: 'checkin', label: '签到与扫一扫', icon: 'pin', group: '在这里，相聚' },
  { id: 'chat', label: '家里聊聊', icon: 'chat', group: '在这里，相聚' },
  { id: 'directory', label: '老乡名录', icon: 'people', group: '在这里，相聚' },
  { id: 'community', label: '互助广场', icon: 'heart', group: '把日子，过好' },
  { id: 'shop', label: '家乡特产', icon: 'grid', group: '把日子，过好' },
  { id: 'resources', label: '资源互换', icon: 'grid', group: '把日子，过好' },
  { id: 'crowdfunding', label: '爱心众筹', icon: 'heart', group: '把日子，过好' },
  { id: 'polls', label: '会员投票', icon: 'check', group: '把日子，过好' },
  { id: 'contacts', label: '联系方式交换', icon: 'people', group: '家里的事' },
  { id: 'ads', label: '合作广告', icon: 'bell', group: '家里的事' },
  { id: 'notices', label: '家乡与公告', icon: 'book', group: '家里的事' },
  { id: 'about', label: '关于我们', icon: 'pin', group: '家里的事' },
  ...(forumEnabled ? [{ id: 'forum', label: '老乡论坛', icon: 'book', group: '家里的事' }] : []),
  ...(staff.value ? [{ id: 'admin', label: '管理工作台', icon: 'grid', group: '平台管理' }] : [])
]);
const titles: Record<string, string> = { gallery: '相聚的日子，值得珍藏', shop: '家乡好物，捎一份乡情', checkin: '到场签到与扫一扫', chat: '熟悉的乡音，从一声问候开始', crowdfunding: '把每份心意，汇成帮助', contacts: '让联系，多一份尊重', ads: '合作展示，连接更多老乡', polls: '一起商量，一起决定', forum: '聊乡音，话家常', resources: '互通有无，让资源流动起来', home: '乡情首页', events: '相聚，总有好时光', community: '有事搭把手，都是自家人', directory: '在苏州，遇见家乡人', notices: '家乡的声音，身边的消息', about: '远离故土，却不远离家乡', account: '我的沭阳之家', admin: '平台管理工作台' };
const { eventView, eventViews, filteredEvents, upcoming } = useEventDiscovery(() => events.value, () => filter.value, () => search.value);
const filteredPosts = computed(() => posts.value.filter(p => (filter.value === '全部' || p.category === filter.value) && (p.title + p.content).includes(search.value)));
const filteredMembers = computed(() => members.value.filter(m => [m.name, m.hometown, m.district, m.industry].join(' ').includes(search.value)));
const memberQuery = ref(''), memberStatus = ref('全部');
const filteredAdminMembers = computed(() => adminMembers.value.filter(m => (memberStatus.value === '全部' || (memberStatus.value === 'disabled' ? !m.enabled : m.status === memberStatus.value)) && [m.name, m.phone, m.memberNo, m.hometown, m.district, m.industry].join(' ').includes(memberQuery.value)));
const pendingCount = computed(() => adminMembers.value.filter(m => m.status === 'pending').length + adminPosts.value.filter(p => p.status === 'pending').length);
const hours = computed(() => signups.value.reduce((sum, s) => sum + Number(s.hours || 0), 0));
const dialogTitle = computed(() => ({ memberDetail: '会员资料', login: '欢迎回家', register: '成为沭阳之家的一员', profile: '完善我的资料', password: '修改登录密码', event: form.value.id ? '编辑活动' : '发起一场相聚', eventDetail: '活动详情', post: '发布互助信息', postDetail: '互助详情', notice: form.value.id ? '编辑公告' : '发布公告', noticeDetail: '消息详情', participants: '报名与签到', reviewMember: '审核入会申请', reviewPost: '审核互助信息', access: '账号权限', reset: '重置账号密码', privacy: '隐私说明与参与约定', confirm: '请确认操作' }[modal.value] || '沭阳之家'));
let toastTimer: ReturnType<typeof setTimeout>;
let refreshGeneration = 0;
const scope = useRequestScope();
let screenGeneration = 0, disposed = false;
function notify(text: string) { message.value = text; clearTimeout(toastTimer); toastTimer = setTimeout(() => message.value = '', 4500); }
function fail(e: unknown) { error.value = e instanceof Error ? e.message : '操作未完成，请重试'; }
async function open(kind: string, data: Row = {}) { const current = scope.capture(), version = ++screenGeneration; beforeModal.value = document.activeElement as HTMLElement; error.value = ''; form.value = { ...data }; modal.value = kind; await nextTick();if (!current() || version !== screenGeneration) return; if (!dialog.value?.open) dialog.value?.showModal(); }
function close() { if (busy.value) return;++screenGeneration; dialog.value?.close(); modal.value = ''; error.value = ''; beforeModal.value?.focus(); }
function expired() { scope.invalidate();++screenGeneration;busy.value = false; ++refreshGeneration; loading.value = false; user.value = null; contactTarget.value = null; chatTarget.value = null; members.value = []; signups.value = []; ownPosts.value = []; adminMembers.value = []; adminPosts.value = []; logs.value = []; events.value = []; posts.value = []; notices.value = []; participants.value = []; selected.value = {}; form.value = {}; dialog.value?.close(); modal.value = ''; }
async function refresh() {
  const generation = ++refreshGeneration;
  const current = () => generation === refreshGeneration;
  loading.value = true;error.value = '';
  try {
    if (user.value) { const me = await api('/auth/me'); if (!current()) return; user.value = me; if (me.mustChangePassword) { await open('password', { oldPassword: '', newPassword: '' }); return; } }
    const data = await Promise.all([api('/home'), api('/events'), api('/posts'), api('/notices')]);
    if (!current()) return;
    [stats.value, events.value, posts.value, notices.value] = data;
    if (user.value && !user.value.mustChangePassword) {
      const personal = await Promise.all([api('/my/signups'), api('/my/posts')]); if (!current()) return; [signups.value, ownPosts.value] = personal;
      if (page.value === 'directory' && approved.value) { const rows = await api('/members'); if (!current()) return; members.value = rows; }
      if (staff.value) { const rows = await Promise.all([api('/admin/members'), api('/admin/posts')]); if (!current()) return; [adminMembers.value, adminPosts.value] = rows; }
      if (page.value === 'admin' && ['superadmin', 'admin'].includes(user.value?.role || '')) { const rows = await api('/admin/audit'); if (!current()) return; logs.value = rows; }
    }
  } catch (e) { if (current()) fail(e); } finally { if (current()) loading.value = false; }
}
async function go(id: string, record = true) { ++screenGeneration; if (id !== 'checkin') checkinTarget.value = null; if (id !== 'chat') chatTarget.value = null; if (id !== 'contacts') contactTarget.value = null; page.value = id;if (record && location.hash !== '#' + id) history.pushState(null, '', '#' + id); filter.value = '全部'; search.value = ''; eventView.value = 'all'; error.value = ''; window.scrollTo({ top: 0 }); if (user.value?.mustChangePassword) return open('password', { oldPassword: '', newPassword: '' }); await refresh(); }
function join() { user.value ? go('account') : open('register', newProfile()); }
function needMember() { if (!user.value) { open('login', { username: '', password: '' }); return false; } if (!approved.value) { notify('请先等待入会审核通过，可在“我的”查看进度'); go('account'); return false; } return true; }
async function act(action: () => Promise<unknown>, success: string, shouldClose = true) {
  if (busy.value) return;const current = scope.capture(), screenVersion = screenGeneration;++refreshGeneration;loading.value = false;busy.value = true;error.value = '';
  try { await action();if (!current()) return;busy.value = false;if (shouldClose && screenVersion === screenGeneration) close();notify(success);await refresh(); }
  catch (e) { if (current() && screenVersion === screenGeneration) fail(e); }finally { if (current()) busy.value = false; }
}
async function loginOrRegister() { const current = scope.capture();await act(async () => { const result = await api('/auth/' + (modal.value === 'register' ? 'register' : 'login'), 'POST', form.value);if (!current()) return;setToken(result.token);user.value = result.user; }, modal.value === 'register' ? '入会申请已提交，请等待志愿团队审核' : '欢迎回家');if (current() && user.value?.mustChangePassword) open('password', { oldPassword: '', newPassword: '' }); }
async function logout() { const current = scope.capture();await act(async () => { await api('/auth/logout', 'POST');if (!current()) return;setToken('');expired();page.value = 'home';history.replaceState(null, '', '#home');notify('已安全退出');await refresh(); }, '已安全退出'); }
async function saveProfile() { const current = scope.capture();await act(async () => { const result = await api('/profile', 'PUT', { ...form.value, resubmit: user.value?.status === 'rejected' });if (current()) user.value = result; }, '资料已保存'); }
async function changePassword() { const current = scope.capture();await act(async () => { const result = await api('/auth/password', 'POST', form.value);if (!current()) return;setToken(result.token);user.value = result.user; }, '密码已更新，其他登录会话已失效'); }
function editProfile() { open('profile', { ...newProfile(), ...user.value }); }
function editEvent(event?: Row) { if (!needMember()) return; open('event', event ? { ...event, startsAt: localTime(event.startsAt), endsAt: localTime(event.endsAt) } : { title: '', category: '乡情聚会', description: '', location: '苏州市木渎镇兵圣路200号', startsAt: '', endsAt: '', capacity: 30, status: 'published' }); }
function localTime(value: string) { return new Date(new Date(value).getTime() + 8 * 3600000).toISOString().slice(0, 16); }
async function saveEvent() { await act(() => api((staff.value ? '/events' : '/event-proposals') + (form.value.id ? '/' + form.value.id : ''), form.value.id ? 'PUT' : 'POST', { ...form.value, startsAt: new Date(form.value.startsAt + ':00+08:00').toISOString(), endsAt: new Date(form.value.endsAt + ':00+08:00').toISOString() }), staff.value ? '活动已保存' : '发起申请已提交审核'); proposalRevision.value++; }
function detail(kind: string, row: Row) { selected.value = row; open(kind, row); }
function signup(event: Row) { if (!needMember()) return; act(() => api('/events/' + event.id + '/signup', 'POST'), '报名成功，在“我的”查看参与记录'); }
async function showParticipants(event: Row) {
  const current = scope.capture();selected.value = event;participants.value = [];await open('participants');const version = screenGeneration;
  const valid = () => current() && version === screenGeneration && modal.value === 'participants' && selected.value.id === event.id;
  if (!valid()) return;try { const rows = await api('/events/' + event.id + '/participants');if (valid()) participants.value = rows; }catch (e) { if (valid()) fail(e); }
}
async function checkin(row: Row) {
  const current = scope.capture(), eventId = selected.value.id, version = screenGeneration;
  await act(async () => { await api('/events/' + eventId + '/check-in', 'POST', { userId: row.userId, hours: Number(row.editHours || 0) });if (!current() || version !== screenGeneration) return;const rows = await api('/events/' + eventId + '/participants');if (current() && version === screenGeneration && modal.value === 'participants') participants.value = rows; }, '签到与时长已记录', false);
}
function newPost() { if (needMember()) open('post', { title: '', category: '生活互助', content: '', contact: '' }); }
function newNotice(notice?: Row) { open('notice', notice || { title: '', category: '平台公告', content: '', status: 'published' }); }
function confirmAction(path: string, text: string) { open('confirm', { path, text }); }
function restorePage() { const id = location.hash.slice(1);if (id === 'account' || nav.value.some(item => item.id === id)) void go(id, false);else void go('home', false); }
onMounted(async () => { const current = scope.capture(); window.addEventListener('popstate', restorePage);window.addEventListener('session-expired', expired);const initial = location.hash.slice(1); if (getToken()) { try { const me = await api('/auth/me');if (!current()) return;user.value = me; }catch (e) { if (!current()) { if (!disposed && !getToken()) await refresh();return; }fail(e); } } if (initial === 'account' || nav.value.some(item => item.id === initial)) page.value = initial;history.replaceState(null, '', '#' + page.value);if (user.value?.mustChangePassword) open('password', { oldPassword: '', newPassword: '' }); else await refresh(); });
onUnmounted(() => { disposed = true;++refreshGeneration;window.removeEventListener('popstate', restorePage);window.removeEventListener('session-expired', expired); clearTimeout(toastTimer); });
</script>

<template>
