="outline" @click="go('about')">先认识一下沭阳之家</button></div><article v-for="event in upcoming.slice(0, 3)" :key="event.id" class="event-row" @click="detail('eventDetail', event)"><div class="date-block"><b>{{ new Date(event.startsAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', day: '2-digit' }) }}</b><span>{{ new Date(event.startsAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', month: 'long' }) }}</span></div><div><span class="tag">{{ event.category }}</span><h3><button class="plain" @click.stop="detail('eventDetail', event)">{{ event.title }}</button></h3><p><Icon name="pin"/>{{ event.location }}</p></div><Icon name="arrow"/></article></section><aside class="home-aside"><div class="section-heading"><div><span class="eyebrow">NEWS FROM HOME</span><h2>家里有新消息</h2></div><button class="text-button" @click="go('notices')" aria-label="全部消息"><Icon name="arrow"/></button></div><div class="notice-panel"><button v-for="notice in notices.filter(n => n.status === 'published').slice(0, 3)" :key="notice.id" class="notice-row" @click="detail('noticeDetail', notice)"><span class="tag">{{ notice.category }}</span><b>{{ notice.title }}</b><small>{{ formatTime(notice.createdAt) }}</small></button><div v-if="!notices.some(n => n.status === 'published')" class="welcome-note"><span class="tag">初次见面</span><h3>不问身份，不设门槛<br>乡音，就是我们的暗号。</h3><p>这是一处由老乡自发共建的公益交流空间。欢迎每一位在外奋斗的家人。</p><button class="text-button" @click="go('about')">读一读我们的故事<Icon name="arrow"/></button></div></div></aside></div>
          <section class="impact-strip"><div><Icon name="heart"/><span>每一份参与<br><b>都让这个家更温暖</b></span></div><div><strong>{{ stats.members ?? '—' }}</strong><span>已加入的家人</span></div><div><strong>{{ stats.events ?? '—' }}</strong><span>已发布的活动</span></div><div><strong>{{ stats.volunteerHours ?? '—' }}<small> h</small></strong><span>累计志愿服务</span></div></section>
        </template>
        <template v-else>
          <div v-if="['events', 'community', 'directory', 'notices', 'about', 'account', 'admin', 'resources', 'crowdfunding', 'contacts', 'ads', 'polls'].includes(page)" class="page-intro"><div><p class="eyebrow">SHUYANG HOME / 沭阳之家</p><h1>{{ titles[page] }}</h1><p>{{ page === 'events' ? '喝杯茶，聊聊天；走出屏幕，见见老乡。' : page === 'community' ? '一条信息，一份善意，让彼此的生活多一点便利。' : '乡情相聚，守望相助。' }}</p></div><button v-if="page === 'events'" class="primary" @click="editEvent()"><Icon name="plus"/>{{ staff ? '发布活动' : '发起活动' }}</button><button v-if="page === 'community'" class="primary" @click="newPost"><Icon name="plus"/>发布互助</button><button v-if="page === 'notices' && staff" class="primary" @click="newNotice()"><Icon name="plus"/>发布公告</button></div>
          <RailwayHub v-if="page === 'railway'" :notices="notices" :manage="staff" @publish="category => newNotice({ title: '', content: '', category, status: 'published', sourceName: category === '一凡说高铁' ? '一凡说高铁' : '', sourceUrl: '', sourceDate: new Date().toISOString().slice(0,10) })" @edit="newNotice"/><GalleryHub v-if="page === 'gallery'" :user="user" @share="go('forum')"/><ShopHub v-if="page === 'shop'" :user="user" @join="join"/><CheckinHub v-if="page === 'checkin'" :user="user" :target="checkinTarget" @join="join"/><h1 v-if="page === 'chat'" class="visually-hidden">{{ titles.chat }}</h1><ChatHub v-if="page === 'chat'" :user="user" :target="chatTarget" @clear-target="chatTarget = null" @join="join"/><SupportHub v-if="page === 'crowdfunding' || page === 'contacts'" :mode="page === 'crowdfunding' ? 'crowdfunding' : 'contacts'" :user="user" :target="contactTarget" @clear-target="contactTarget = null" @join="join"/><EngagementHub v-if="page === 'ads' || page === 'polls'" :mode="page === 'ads' ? 'ads' : 'polls'" :user="user" @join="join"/><template v-if="page === 'events' || page === 'community'">
            <AdPlacements v-if="page === 'events'" placement="events"/><div class="filterbar"><div class="chips"><button v-for="category in ['全部', ...(page === 'events' ? eventCategories : postCategories)]" :key="category" :class="{ selected: filter === category }" @click="filter = category">{{ category }}</button></div><label class="search-box"><Icon name="search"/><input v-model="search" :placeholder="page === 'events' ? '搜索活动、地点' : '搜索互助信息'" aria-label="搜索内容"></label></div>
            <div v-if="page === 'events'" class="event-status-filters" aria-label="活动状态筛选"><button v-for="item in eventViews.filter(item => item.id !== 'mine' || approved)" :key="item.id" class="outline" :class="{ active: eventView === item.id }" :aria-pressed="eventView === item.id" @click="eventView = item.id">{{ item.label }}</button><span role="status">找到 {{ filteredEvents.length }} 场活动</span></div><div v-if="page === 'events'" class="cards-grid"><article v-for="event in filteredEvents" :key="event.id" class="event-card"><div :class="['event-banner', { volunteer: event.category === '公益志愿' }]"><Icon :name="event.category === '公益志愿' ? 'heart' : 'calendar'"/><span>{{ event.category }}</span><span class="banner-state">{{ eventState(event) }}</span></div><div class="card-body"><h3><button class="plain" @click="detail('eventDetail', event)">{{ event.title }}</button></h3><p class="meta"><Icon name="clock"/>{{ formatTime(event.startsAt) }} · 北京时间</p><p class="meta"><Icon name="pin"/>{{ event.location }}</p><p class="excerpt">{{ event.description }}</p><div class="card-footer"><span>{{ event.registered }} / {{ event.capacity }} 人报名</span><button class="text-button" @click="detail('eventDetail', event)">{{ event.mySignup ? '已报名 · 查看' : '查看详情' }}<Icon name="arrow"/></button></div><div v-if="staff" class="admin-inline"><button @click="editEvent(event)">编辑</button><button @click="showParticipants(event)">报名与签到</button></div></div></article></div>
            <div v-else class="cards-grid"><article v-for="post in filteredPosts" :key="post.id" class="post-card"><span class="tag">{{ post.category }}</span><h3><button class="plain" @click="detail('postDetail', post)">{{ post.title }}</button></h3><p class="excerpt">{{ post.content }}</p><div class="card-footer"><span>{{ post.authorName }} · {{ formatTime(post.createdAt) }}</span><button class="text-button" @click="detail('postDetail', post)">详情<Icon name="arrow"/></button></div></article></div>
            <div v-if="!loading && !error && !(page === 'events' ? filteredEvents.length : filteredPosts.length)" class="empty"><Icon :name="page === 'events' ? 'calendar' : 'heart'"/><h3>{{ search || filter !== '全部' || eventView !== 'all' ? '暂时没有匹配的内容' : page === 'events' ? '还没有发布活动' : '第一份互助，从你开始' }}</h3><p>{{ page === 'events' ? '新活动发布后会展示在这里，欢迎常回来看看。' : '分享一个机会，或说出你的需要。发布内容审核通过后展示。' }}</p><button v-if="search || filter !== '全部' || (page === 'events' && eventView !== 'all')" class="outline" @click="search = ''; filter = '全部'; eventView = 'all'">清除筛选</button><button v-if="page === 'community'" class="outline" @click="newPost">发布一条互助</button></div>
          </template>
          <EngagementHub v-if="page === 'events' && user" mode="activities" :user="user" :refresh-key="proposalRevision" @join="join" @updated="refresh"/><ForumHub v-if="page === 'forum'" :user="user" @join="join"/><CommunityHub v-if="page === 'resources'" mode="resources" :user="user" @join="join"/>
          <template v-if="page === 'directory'">
            <div v-if="!approved" class="empty"><Icon name="people"/><h3>加入后，认识更多家乡人</h3><p>名录仅对已审核会员开放，展示内容由每位老乡自主选择。</p><button class="primary" @click="join">{{ user ? '查看入会状态' : '申请加入' }}</button></div>
            <template v-else><div class="filterbar"><p>仅展示自愿公开资料的会员</p><label class="search-box"><Icon name="search"/><input v-model="search" placeholder="姓名、乡镇、行业" aria-label="搜索会员"></label></div><div class="cards-grid"><article v-for="member in filteredMembers" :key="member.id" class="member-card"><div class="avatar large">{{ member.name.slice(0, 1) }}</div><h3>{{ member.name }}<span v-if="member.volunteer" class="tag">志愿意向</span></h3><p>{{ member.hometown }} · {{ member.district }}</p><p>{{ member.industry || '期待与你交流' }}</p><p class="excerpt">{{ member.bio }}</p><a v-if="member.phone" :href="'tel:' + member.phone" class="text-button">{{ member.phone }}</a><button v-if="member.id !== user?.id" class="primary" @click="chatMember(member)">站内聊聊</button><button v-if="member.id !== user?.id" class="outline" @click="contactMember(member)">申请交换联系方式</button></article></div><div v-if="!filteredMembers.length" class="empty"><h3>暂时没有公开资料</h3><p>你可以在个人中心选择将自己加入老乡名录。</p><button class="outline" @click="editProfile">设置公开偏好</button></div></template>
          </template>
          <template v-if="page === 'notices'"><div class="notice-list"><article v-for="notice in notices" :key="notice.id" class="panel"><span class="tag">{{ notice.category }}{{ notice.status === 'withdrawn' ? ' · 已撤下' : '' }}</span><h2><button class="plain" @click="detail('noticeDetail', notice)">{{ notice.title }}</button></h2><p class="prose">{{ notice.content }}</p><div class="card-footer"><small>{{ formatTime(notice.createdAt) }}</small><button v-if="staff" class="text-button" @click="newNotice(notice)">编辑公告</button></div></article><div v-if="!notices.length" class="empty"><Icon name="book"/><h3>家乡的消息，敬请期待</h3><p>公告、家乡故事将在这里与大家见面。</p></div></div></template>
          <template v-if="page === 'about'"><section class="about-feature"><div><p class="eyebrow">我们的故事</p><h2>以乡音牵起乡愁，<br>以乡情温暖他乡。</h2><p>苏州沭阳之家由一凡小哥（周学超）发起，扎根苏州，是民间自发组建、无官方注册、不属于社团组织、非商业盈利的乡情交流群体。</p><p>这里没有身份高低，没有职位门槛。面向所有在苏州生活、务工、打拼、创业的沭阳老乡，兼顾普通在外打工人、青年创业者，让身在姑苏的沭阳人拥有一份家的温暖。</p><div class="values"><span>乡情交友</span><span>互助发展</span><span>信息共享</span><span>文化传承</span><span>公益慈善</span></div></div><aside class="contact-card"><Icon name="pin"/><h3>来家里坐坐</h3><p>苏州市木渎镇兵圣路200号</p><p>活动场地、水电及基础设施<br>由沭阳老乡陈军无偿公益提供</p><hr><small>联系一凡小哥（周学超）</small><a href="tel:13862597517">138 6259 7517</a><p>日常运营与活动服务<br>由热心乡情志愿者义务承担</p></aside></section><img class="introduction-poster" src="/brand/introduction.jpg" alt="沭阳之家介绍：平台宗旨、志愿者团队、活动地点和联系方式"><section class="panel"><h2>自愿参与，温暖同行</h2><p class="prose">{{ agreement }}</p><button class="text-button" @click="open('privacy')">查看隐私说明<Icon name="arrow"/></button></section></template>
          <template v-if="page === 'account'">
            <section v-if="!user" class="member-welcome" aria-labelledby="member-welcome-title">
              <div class="member-welcome-mark"><Icon name="user"/></div>
              <p class="member-welcome-eyebrow">一份乡情，从这里相连</p>
              <h2 id="member-welcome-title">欢迎加入沭阳之家</h2>
              <p class="member-welcome-copy">登录，看看你的会员卡与参与记录。<br>第一次来，也欢迎成为家里的一员。</p>
              <ul class="member-welcome-benefits"><li><Icon name="user"/>电子会员卡</li><li><Icon name="calendar"/>乡情活动</li><li><Icon name="heart"/>志愿服务</li></ul>
              <div class="button-row member-welcome-actions"><button class="primary" @click="open('login', { username: '', password: '' })">登录账号<Icon name="arrow"/></button><button class="outline" @click="join">申请入会</button></div>
              <p class="member-welcome-note">自愿加入，个人资料默认不公开。</p>
            </section>
            <template v-else><div class="account-grid"><section class="membership-card"><div><img src="/brand/logo.png" alt=""><span>沭阳之家 · 电子会员卡</span></div><p>乡情相聚，守望相助</p><h2>{{ user.name }}</h2><span class="card-status">{{ statusNames[user.status] }} · {{ roleNames[user.role] }}</span><small>会员编号</small><code>{{ user.memberNo || '审核通过后生成' }}</code></section><section class="panel"><h2>我的参与</h2><div class="my-stats"><div><strong>{{ signups.filter(s => s.status !== 'cancelled').length }}</strong><span>活动报名</span></div><div><strong>{{ hours }}<small> h</small></strong><span>志愿服务</span></div><div><strong>{{ ownPosts.length }}</strong><span>互助发布</span></div></div><div class="button-row"><button class="outline" @click="editProfile">编辑资料</button><button class="outline" @click="open('password', { oldPassword: '', newPassword: '' })">修改密码</button><button class="text-button" @click="logout">退出登录</button></div><p v-if="user.status !== 'approved'" class="status-note">{{ user.status === 'pending' ? '你的申请已提交，志愿团队审核后即可参加活动。' : '申请已退回：' + user.reviewNote + '。请修改资料后重新提交。' }}</p></section></div>
            <div class="button-row account-community"><button v-if="staff" class="primary" @click="go('admin')">管理工作台</button><button class="outline" @click="go('chat')">家里聊聊 <span v-if="unread">{{ unread }}</span></button><button class="outline" @click="go('crowdfunding')">我的众筹与支持</button><button class="outline" @click="go('contacts')">联系方式交换</button><button v-if="forumEnabled" class="outline" @click="go('forum')">我的论坛话题</button><button class="outline" @click="go('polls')">会员投票</button><button class="outline" @click="go('ads')">广告申请</button><button class="outline" @click="go('resources')">我的资源与交换</button><button class="outline" @click="go('directory')">老乡名录</button></div><section class="panel"><div class="section-heading"><h2>我的活动</h2><button class="text-button" @click="go('events')">去看看活动<Icon name="arrow"/></button></div><div v-if="!signups.length" class="inline-empty">还没有报名活动，下一次相聚见。</div><div v-for="signupRow in signups" :key="signupRow.id" class="record-row"><div><b>{{ signupRow.event.title }}</b><p>{{ formatTime(signupRow.event.startsAt) }} · {{ signupRow.event.location }}</p></div><span class="tag">{{ statusNames[signupRow.status] }}{{ signupRow.hours ? ' · ' + signupRow.hours + '小时' : '' }}</span><button v-if="canCancelSignup(signupRow)" class="text-button" @click="confirmAction('/events/' + signupRow.eventId + '/cancel-signup', '确认取消这场活动的报名？名额将释放给其他老乡。')">取消报名</button><span v-else-if="signupRow.status === 'registered'" class="form-tip">活动已开始，取消参与请联系组织者。</span></div></section>
            <section class="panel"><h2>我的互助</h2><div v-if="!ownPosts.length" class="inline-empty">暂未发布互助信息。</div><div v-for="post in ownPosts" :key="post.id" class="record-row"><div><b>{{ post.title }}</b><p>{{ post.reviewNote || post.category }}</p></div><span class="tag">{{ statusNames[post.status] }}</span><button v-if="post.status !== 'closed'" class="text-button" @click="confirmAction('/posts/' + post.id + '/close', '确认关闭这条互助信息？关闭后不再展示。')">关闭信息</button></div></section></template>
          </template>
          <template v-if="page === 'admin' && staff"><div class="chips admin-tabs"><button v-for="tab in [{ id: 'members', label: '会员与入会' }, { id: 'posts', label: '互助审核' }, ...(forumEnabled ? [{ id: 'forum', label: '论坛管理' }] : []), { id: 'activities', label: '活动发起审核' }, { id: 'crowdfunding', label: '众筹审核' }, { id: 'ads', label: '广告管理' }, { id: 'polls', label: '投票管理' }, { id: 'resources', label: '资源管理' }, { id: 'audit', label: '操作日志' }]" v-show="tab.id !== 'audit' || ['superadmin', 'admin'].includes(user?.role || '')" :key="tab.id" :class="{ selected: adminTab === tab.id }" @click="adminTab = tab.id">{{ tab.label }}</button><button @click="go('events')">活动管理 ↗</button><button @click="go('notices')">公告管理 ↗</button></div><SupportHub v-if="adminTab === 'crowdfunding'" mode="crowdfunding" :user="user" manage @join="join"/><EngagementHub v-if="['activities', 'ads', 'polls'].includes(adminTab)" :mode="adminTab === 'activities' ? 'activities' : adminTab === 'ads' ? 'ads' : 'polls'" :user="user" manage @join="join" @updated="refresh"/><ForumHub v-if="adminTab === 'forum'" :user="user" manage @join="join"/><CommunityHub v-if="adminTab === 'resources'" mode="resources" :user="user" manage @join="join"/><section class="panel table-wrap" v-if="adminTab === 'members'"><div class="filterbar"><label class="search-box"><Icon name="search"/><input v-model="memberQuery" placeholder="姓名、手机、会员编号、地区" aria-label="搜索管理会员"></label><select v-model="memberStatus" class="filter-select" aria-label="会员状态筛选"><option value="全部">全部会员</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已退回</option><option value="disabled">已停用</option></select></div><table><thead><tr><th>会员</th><th>家乡 / 现居地</th><th>申请状态</th><th>角色 / 账号</th><th>操作</th></tr></thead><tbody><tr v-for="member in filteredAdminMembers" :key="member.id"><td><b>{{ member.name }}</b><small>{{ member.phone || member.username }}</small></td><td>{{ member.hometown || '—' }}<small>{{ member.district }}</small></td><td><span class="tag">{{ statusNames[member.status] }}</span></td><td>{{ roleNames[member.role] }}<small>{{ member.enabled ? '已启用' : '已停用' }}</small></td><td><div class="button-row"><button class="text-button" @click="detail('memberDetail', member)">资料</button><button v-if="member.status === 'pending'" class="text-button" @click="detail('reviewMember', { ...member, status: 'approved', note: '' })">审核申请</button><button v-if="['superadmin', 'admin'].includes(user?.role || '')" class="text-button" @click="detail('access', member)">权限</button><button v-if="['superadmin', 'admin'].includes(user?.role || '')" class="text-button" @click="detail('reset', { ...member, password: '' })">重置密码</button></div></td></tr></tbody></table></section><section v-if="adminTab === 'posts'" class="panel"><div v-if="!adminPosts.length" class="inline-empty">没有待处理的互助信息。</div><div v-for="post in adminPosts" :key="post.id" class="record-row"><div><b>{{ post.title }}</b><p>{{ post.authorName }} · {{ post.category }}</p></div><span class="tag">{{ statusNames[post.status] }}</span><button v-if="post.status === 'pending'" class="text-button" @click="detail('reviewPost', { ...post, status: 'approved', note: '' })">审核内容</button><button v-else-if="post.status === 'approved'" class="text-button" @click="confirmAction('/posts/' + post.id + '/close', '确认下架这条互助信息？')">下架</button></div></section><section v-if="adminTab === 'audit' && ['superadmin', 'admin'].includes(user?.role || '')" class="panel table-wrap"><p>最近200条操作记录</p><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象编号</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td>{{ formatTime(log.time) }}</td><td>{{ log.operator }}</td><td>{{ log.action }}</td><td class="id-cell">{{ log.target }}</td></tr></tbody></table></section></template>
        </template>
        <footer><span>沭阳之家 <b>·</b> 因为有你，家更温暖。</span><button class="text-button" @click="open('privacy')">隐私与参与约定</button><span>公益交流 · 自愿参与</span></footer>
      </div>
    </main>
    <nav class="mobile-nav" aria-label="手机导航"><button v-for="item in [{ id: 'home', label: '首页', icon: 'home' }, { id: 'events', label: '活动', icon: 'calendar' }, { id: 'community', label: '互助', icon: 'heart' }, { id: 'account', label: '我的', icon: 'user' }]" :key="item.id" :class="{ active: page === item.id }" @click="go(item.id)"><Icon :name="item.icon"/><span>{{ item.label }}</span></button><button :class="{ active: page === 'chat' }" @click="go('chat')"><Icon name="chat"/><span>消息 {{ unread || '' }}</span></button></nav>
    <div v-if="message" class="toast" role="status"><Icon name="check"/>{{ message }}</div>

    <dialog ref="dialog" class="modal" aria-labelledby="dialog-title" @cancel.prevent="close" @click="($event.target === dialog) && close()"><div class="modal-inner"><header><div><span class="eyebrow">SHUYANG HOME</span><h2 id="dialog-title">{{ dialogTitle }}</h2></div><button class="close-button" aria-label="关闭弹窗" :disabled="busy" @click="close">×</button></header><p v-if="error" class="form-error" role="alert">{{ error }}</p>
      <form v-if="modal === 'login'" @submit.prevent="loginOrRegister"><p>一声乡音，就是回家的路。</p><label>手机号 / 管理员账号<input v-model="form.username" required autocomplete="username" maxlength="80" placeholder="请输入账号"></label><label>登录密码<input v-model="form.password" type="password" required autocomplete="current-password" maxlength="128" placeholder="请输入密码"></label><button class="primary full" :disabled="busy">{{ busy ? '正在登录…' : '登录，回家看看' }}</button><p class="form-tip">还没加入？<button type="button" class="text-button" @click="open('register', newProfile())">申请入会</button></p><p class="form-tip">忘记密码请联系平台核实身份：13862597517</p></form>
      <form v-if="modal === 'register' || modal === 'profile'" @submit.prevent="modal === 'register' ? loginOrRegister() : saveProfile()"><p>填写一点关于你的信息，让家乡人认识你。默认不公开。</p><div class="form-grid"><label>姓名<input v-model="form.name" required minlength="2" maxlength="30" autocomplete="name"></label><label v-if="modal === 'register'">手机号<input v-model="form.phone" required pattern="1[3-9][0-9]{9}" maxlength="11" inputmode="tel" autocomplete="tel"></label><label>家乡乡镇<input v-model="form.hometown" required minlength="2" maxlength="50" placeholder="例如：沭阳 · 沭城街道"></label><label>现居地区<input v-model="form.district" required minlength="2" maxlength="50" placeholder="例如：苏州 · 吴中区"></label><label>行业 / 职业<input v-model="form.industry" maxlength="50" placeholder="选填"></label></div><label v-if="modal === 'register'">设置密码<input v-model="form.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="至少12位，包含字母和数字"></label><label>一句话介绍自己<textarea v-model="form.bio" maxlength="300" rows="3" placeholder="兴趣、擅长的事，或想认识怎样的朋友（选填）"></textarea></label><label class="checkbox"><input v-model="form.volunteer" type="checkbox">我愿意参与志愿服务</label><label class="checkbox"><input v-model="form.directoryVisible" type="checkbox">向已审核会员公开我的名录资料</label><label class="checkbox"><input v-model="form.phoneVisible" type="checkbox">在公开名录中同时展示我的手机号</label><details class="privacy-details"><summary>阅读隐私说明与参与约定</summary><p>{{ privacy }}</p><p>{{ agreement }}</p></details><label v-if="modal === 'register'" class="checkbox"><input v-model="form.consent" type="checkbox" required>我已阅读并同意隐私说明及自愿参与约定</label><button class="primary full" :disabled="busy">{{ busy ? '正在提交…' : modal === 'register' ? '提交入会申请' : user?.status === 'rejected' ? '保存并重新申请' : '保存资料' }}</button></form>
      <form v-if="modal === 'password'" @submit.prevent="changePassword()"><p v-if="user?.mustChangePassword">为保护账号，请先修改管理员设置的初始密码。</p><label>原密码<input v-model="form.oldPassword" type="password" required autocomplete="current-password" maxlength="128"></label><label>新密码<input v-model="form.newPassword" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="至少12位，包含字母和数字"></label><button class="primary full" :disabled="busy">更新密码</button></form>
      <form v-if="modal === 'event'" @submit.prevent="saveEvent"><label>活动名称<input v-model="form.title" required minlength="2" maxlength="80"></label><div class="form-grid"><label>活动类型<select v-model="form.category"><option v-for="category in eventCategories" :key="category">{{ category }}</option></select></label><label>人数上限<input v-model="form.capacity" type="number" min="1" max="10000" required></label><label>开始时间（北京时间）<input v-model="form.startsAt" type="datetime-local" required></label><label>结束时间（北京时间）<input v-model="form.endsAt" type="datetime-local" required></label></div><label>活动地点<input v-model="form.location" required minlength="2" maxlength="150"></label><label>活动详情<textarea v-model="form.description" required minlength="10" maxlength="5000" rows="5" placeholder="介绍活动安排、集合点与参与须知"></textarea></label><label v-if="staff">发布状态<select v-model="form.status"><option value="published">公开发布</option><option value="draft">保存草稿</option><option v-if="form.id" value="cancelled">取消活动</option></select></label><p class="form-tip">已有报名后不能修改时间与活动类型；取消活动会同步取消报名。</p><button class="primary full" :disabled="busy">{{ staff ? '保存活动' : '提交发起申请' }}</button></form>
      <div v-if="modal === 'eventDetail'"><span class="tag">{{ form.category }} · {{ eventState(form) }}</span><h2>{{ form.title }}</h2><button v-if="form.mySignup || staff" class="outline" @click="beginCheckin(form)">地点签到／扫码</button><p class="meta"><Icon name="clock"/>{{ formatTime(form.startsAt) }} — {{ formatTime(form.endsAt) }}（北京时间）</p><p class="meta"><Icon name="pin"/>{{ form.location }}</p><p class="prose">{{ form.description }}</p><p>{{ form.registered }} / {{ form.capacity }} 人报名 · 自愿参与</p><button class="primary full" :disabled="busy || !!form.mySignup || eventState(form) !== '报名中'" @click="signup(form)">{{ signupLabel(form) }}</button></div>
      <form v-if="modal === 'post'" @submit.prevent="act(() => api('/posts', 'POST', form), '已提交审核，通过后将在互助广场展示')"><label>标题<input v-model="form.title" required minlength="2" maxlength="80"></label><label>分类<select v-model="form.category"><option v-for="category in postCategories" :key="category">{{ category }}</option></select></label><label>具体内容<textarea v-model="form.content" required minlength="10" maxlength="3000" rows="6" placeholder="清楚说明你的需求或可以提供的帮助，请勿在正文填写个人敏感信息"></textarea></label><label>联系方式（选填）<input v-model="form.contact" maxlength="80" placeholder="审核通过的会员可见"></label><p class="form-tip">内容审核通过后公开展示，请勿发布未经核实的招聘、投资或收费信息。</p><button class="primary full" :disabled="busy">提交审核</button></form>
      <div v-if="modal === 'postDetail'"><span class="tag">{{ form.category }}</span><h2>{{ form.title }}</h2><p class="prose">{{ form.content }}</p><p>{{ form.authorName }} · {{ formatTime(form.createdAt) }}</p><div class="status-note">{{ form.contact ? '联系方式：' + form.contact : approved ? '发布者未填写联系方式' : '联系方式仅向已审核会员展示' }}</div></div>
      <form v-if="modal === 'notice'" @submit.prevent="act(() => api('/notices' + (form.id ? '/' + form.id : ''), form.id ? 'PUT' : 'POST', form), '公告已保存')"><label>标题<input v-model="form.title" required minlength="2" maxlength="80"></label><label>分类<select v-model="form.category"><option>平台公告</option><option>家乡文化</option><option>淮新高铁</option><option>一凡说高铁</option></select></label><label>内容<textarea v-model="form.content" required minlength="5" maxlength="5000" rows="8" :placeholder="['淮新高铁','一凡说高铁'].includes(form.category) ? '说明已确认的信息与原文出处；个人解读请与消息事实区分。' : '请输入公告内容'"></textarea></label><template v-if="['淮新高铁','一凡说高铁'].includes(form.category)"><div class="form-grid"><label>来源名称<input v-model="form.sourceName" :required="form.status === 'published'" maxlength="100" placeholder="发布机构或作者"></label><label>来源日期<input v-model="form.sourceDate" type="date" :required="form.status === 'published'"></label></div><label>原文链接<input v-model="form.sourceUrl" type="url" :required="form.category === '淮新高铁' && form.status === 'published'" maxlength="1000" placeholder="https://..."></label><p class="form-tip">专题资讯注明原文出处；“一凡说高铁”归入一凡解读栏目。</p></template><label>状态<select v-model="form.status"><option value="published">公开发布</option><option value="withdrawn">撤下</option></select></label><button class="primary full" :disabled="busy">保存公告</button></form>
      <div v-if="modal === 'noticeDetail'"><span class="tag">{{ form.category }}</span><h2>{{ form.title }}</h2><p class="prose">{{ form.content }}</p><small>{{ formatTime(form.createdAt) }}</small></div>
      <div v-if="modal === 'participants'"><h3>{{ selected.title }}</h3><p class="form-tip">活动开始后可签到。志愿时长以0.25小时为单位，不超过活动时长及24小时，确认后不能重复变更。</p><div v-if="!participants.length" class="inline-empty">还没有人报名。</div><div v-for="person in participants" :key="person.id" class="participant"><div><b>{{ person.name }}</b><p>{{ person.phone }}</p></div><span v-if="person.status === 'checked_in' && person.hoursFinalized !== false" class="tag">已签到 · {{ person.hours }} h</span><template v-else><label v-if="selected.category === '公益志愿'">服务小时<input v-model="person.editHours" type="number" min="0" max="24" step="0.25" placeholder="0"></label><button class="outline" :disabled="busy" @click="checkin(person)">确认签到</button></template></div></div>
      <form v-if="modal === 'reviewMember' || modal === 'reviewPost'" @submit.prevent="act(() => api(modal === 'reviewMember' ? '/admin/members/' + form.id + '/review' : '/posts/' + form.id + '/review', 'POST', form), '审核结果已保存')"><h3>{{ form.name || form.title }}</h3><p class="prose">{{ modal === 'reviewMember' ? [form.phone, form.hometown, form.district, form.industry, form.bio].filter(Boolean).join(' · ') : form.content }}</p><label>审核结果<select v-model="form.status"><option value="approved">通过</option><option value="rejected">退回</option></select></label><label>审核说明<textarea v-model="form.note" :required="form.status === 'rejected'" :minlength="form.status === 'rejected' ? 2 : 0" maxlength="300" rows="3" placeholder="退回时请说明需要修改的内容"></textarea></label><button class="primary full" :disabled="busy">确认审核</button></form>
      <div v-if="modal === 'memberDetail'"><h3>{{ form.name }}</h3><p class="prose">{{ [form.phone, form.memberNo, form.hometown, form.district, form.industry, form.bio].filter(Boolean).join('\n') }}</p><p>{{ statusNames[form.status] }} · {{ roleNames[form.role] }} · {{ form.enabled ? '已启用' : '已停用' }}</p><p class="status-note">{{ form.volunteer ? '愿意参与志愿服务' : '未登记志愿意向' }} · {{ form.directoryVisible ? '已公开名录资料' : '未公开名录资料' }}</p></div><form v-if="modal === 'access'" @submit.prevent="act(() => api('/admin/members/' + form.id + '/access', 'POST', form), '账号权限已更新，该账号需重新登录')"><h3>{{ form.name }}</h3><label>角色<select v-model="form.role" :disabled="user?.role !== 'superadmin'"><option value="member">会员</option><option value="organizer">志愿组织者</option><option value="moderator">版主</option><option value="admin">普通管理员</option><option value="superadmin">超级管理员</option></select></label><label v-if="form.role === 'moderator'">负责板块<select v-model="form.forumBoards" multiple><option v-for="board in ['乡情闲聊', '苏州生活', '创业交流', '家乡故事']" :key="board">{{ board }}</option></select></label><label class="checkbox"><input v-model="form.enabled" type="checkbox">启用账号</label><p class="form-tip">修改权限会使该账号所有已登录会话失效。</p><button class="primary full" :disabled="busy">保存权限</button></form>
      <form v-if="modal === 'reset'" @submit.prevent="act(() => api('/admin/members/' + form.id + '/reset-password', 'POST', form), '密码已重置，请安全告知会员首次登录修改')"><h3>{{ form.name }}</h3><label>临时密码<input v-model="form.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p class="form-tip">至少12位，含字母与数字。请先核实本人身份，线下安全告知。账号下次登录必须修改。</p><button class="primary full" :disabled="busy">确认重置</button></form>
      <div v-if="modal === 'privacy'"><h3>个人资料与隐私</h3><p class="prose">{{ privacy }}</p><h3>自愿参与约定</h3><p class="prose">{{ agreement }}</p><small>版本：2026-10-27</small></div>
      <div v-if="modal === 'confirm'"><p>{{ form.text }}</p><div class="button-row"><button class="outline" :disabled="busy" @click="close">返回</button><button class="primary" :disabled="busy" @click="act(() => api(form.path, 'POST'), '操作已完成')">确认</button></div></div>
    </div></dialog>
  </div>
</template>

<style scoped>
.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.event-status-filters{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:16px 0}.event-status-filters button{margin:0;padding:10px 14px;min-height:44px}.event-status-filters .active{background:#243f55;color:white;border-color:#243f55}.event-status-filters span{font-size:14px;color:#5f7078}
